def run(values):
 value='outer'
 rows=[(value,locals()['value'],locals()['values']) for value in values]
 return rows,value,'value' in locals()
print(run([1,2]))

def run():
 last=-1
 values=[(last:=x+y) for x in range(3) if x for y in range(2)]
 return values,last,'x' in locals(),'y' in locals()
print(run())
